    [Fact]
    public void AbAndCdPairOnlyWithinSameObjectFaceAndHeightRound()
    {
        var aggregator = new FaceResultAggregator();
        var first = new FaceResultKey("object-1", 1, 1);
        var nextRound = new FaceResultKey("object-1", 1, 2);
        Assert.Null(aggregator.Add(first, Image("A")));
        Assert.Null(aggregator.Add(nextRound, Image("B")));
        Assert.Equal(2, aggregator.IncompleteKeys.Count);
        var pair = aggregator.Add(first, Image("B"));
        Assert.NotNull(pair);
        Assert.Equal("A", pair.First.Camera);
        Assert.Equal("B", pair.Second.Camera);
        Assert.Single(aggregator.IncompleteKeys);
        var cd = new FaceResultKey("object-2", 1, 1);
        Assert.Null(aggregator.Add(cd, Image("C")));
        Assert.Equal("D", aggregator.Add(cd, Image("D"))!.Second.Camera);
        Assert.Throws<InvalidDataException>(() => aggregator.Add(first, Image("A")));
    }

    private static FaceImageResult Image(string camera) => new(camera,
        new MediaRef(Guid.NewGuid(), Guid.NewGuid(), Guid.NewGuid(), "Detection",
            "media/test.png", 32, "png", "Test/FixedImage", "plan", "point",
            "FileCompleted"), "OK", "worker://test");
}

[Fact]
public async Task Q03HandoffResolvesBothFacesFromInitialMeasurement()
{
    var root = TestConfiguration.Workspace();
    var catalog = TestConfiguration.RecipeCatalog(Path.Combine(root, "specs",
        "008-recipe-driven-inspection", "fixtures", "recipes-q03.json"));
    var plan = RecipeRunPlanner.Build(catalog, "q03-current-round", "S1",
        "TEST-TRAY-0103", ["P01"]);
    var revision = RecipePlanRevision.Compute(plan);
    var runId = Guid.NewGuid();
    var trayId = Guid.NewGuid();
    var callId = Guid.NewGuid();
    var now = DateTimeOffset.UtcNow;
    var identity = new WorkflowIdentity(runId, trayId, Guid.NewGuid().ToString("D"),
        Guid.NewGuid().ToString("D"), "q03-current-round", "S1", ["P01"], now,
        "test:Operator", RunPurpose.Test, "public-1", "budget-1", "sim-1");
    var handoff = new PublicPreparationHandoffV2(
        PublicPreparationHandoffV2.CurrentSchemaVersion, Guid.NewGuid(), identity,
        "test-points", "test-capabilities", ["media://first-3d"], ["media://f"],
        [$"algorithm-call://{callId:D}"], "TEST-TRAY-0103", "recipe-plan://q03",
        revision, "recipe-binding://q03", ComponentEvidenceSource.Test,
        "Test", ["write://q03"], Guid.NewGuid(), 1, now, "");
    handoff = handoff with { PayloadDigest = PublicPreparationHandoffV2.ComputePayloadDigest(handoff) };
    var query = new FixedHandoffQuery(new(handoff, handoff.HandoffId,
        handoff.WriteId, handoff.CommittedRevision, handoff.PayloadDigest));
    var config = JsonSerializer.Deserialize<PublicConfiguration>(File.ReadAllText(
        Path.Combine(root, "specs", "007-station01-integrated-loop", "examples",
            "public.virtual-loop.json")), new JsonSerializerOptions(JsonSerializerDefaults.Web))!;
    var height = new HeightResult(runId, Guid.NewGuid(), callId,
        "sim-whole-tray", "1.0.0",
        [HeightSample.FromRaw("sample-a", 10.5, "mm", "SIM_REFERENCE")],
        AlgorithmState.Success);
    var request = await new PublicPreparationHandoffV2Consumer(query)
        .CreateDetectionRequestAsync(runId, trayId, revision, Guid.NewGuid(), 1,
            now.AddMinutes(4), "q03-first", plan, strictRecipeExecution: true,
            motionConfiguration: config, heightResult: height,
            recipeApplicationReceipt: SemanticRecipeReceiptFixture.For(handoff));
    Assert.Equal(4, request.Targets!.Count);
    Assert.All(request.Targets!, target => {
        Assert.Equal(1, target.HeightRound);
    });
    Assert.Equal([110.5, 110.5], request.Targets.Where(x => x.LocalFace == 1)
        .Select(x => x.Point.Z).ToArray());
    Assert.Equal([112.5, 112.5], request.Targets.Where(x => x.LocalFace == 2)
        .Select(x => x.Point.Z).ToArray());
}

