[Fact]
public async Task TestTargetsUseMatchingCurrentThreeDHeightAndRejectWrongSample()
{
    var root = TestConfiguration.Workspace();
    var catalog = TestConfiguration.RecipeCatalog(Path.Combine(root, "specs",
        "008-recipe-driven-inspection", "fixtures", "recipes-q02.json"));
    var plan = RecipeRunPlanner.BuildExecutable(catalog, "test-height", "S1",
        "TEST-TRAY-0202", ["P01", "P03"]);
    var revision = RecipePlanRevision.Compute(plan);
    var runId = Guid.NewGuid();
    var trayId = Guid.NewGuid();
    var callId = Guid.NewGuid();
    var now = DateTimeOffset.UtcNow;
    var identity = new WorkflowIdentity(runId, trayId, Guid.NewGuid().ToString("D"),
        Guid.NewGuid().ToString("D"), "test-height", "S1", ["P01", "P03"], now,
        "test:Operator", RunPurpose.Test, "public-1", "budget-1", "sim-1");
    var handoff = new PublicPreparationHandoffV2(
        PublicPreparationHandoffV2.CurrentSchemaVersion, Guid.NewGuid(), identity,
        "test-points-1", "capability-1", ["media://3d"], ["media://f"],
        [$"algorithm-call://{callId:D}"], "TEST-TRAY-0202", "recipe-plan://test",
        revision, "recipe-binding://test", ComponentEvidenceSource.Simulated,
        "Verified", ["write://test"], Guid.NewGuid(), 1, now, "");
    handoff = handoff with { PayloadDigest = PublicPreparationHandoffV2.ComputePayloadDigest(handoff) };
    var query = new FixedHandoffQuery(new(handoff, handoff.HandoffId, handoff.WriteId,
        handoff.CommittedRevision, handoff.PayloadDigest));
    var consumer = new PublicPreparationHandoffV2Consumer(query);
    var config = JsonSerializer.Deserialize<PublicConfiguration>(File.ReadAllText(
        Path.Combine(root, "specs", "007-station01-integrated-loop", "examples",
            "public.virtual-loop.json")), new JsonSerializerOptions(JsonSerializerDefaults.Web))!;
    HeightResult Height(double a, double b) => new(runId, Guid.NewGuid(), callId,
        "sim-whole-tray", "1.0.0",
        [HeightSample.FromRaw("sample-a", a, "mm", "SIM_REFERENCE"),
         HeightSample.FromRaw("sample-b", b, "mm", "SIM_REFERENCE")],
        AlgorithmState.Success);
    Task<DetectionRequest> Resolve(HeightResult height) =>
        consumer.CreateDetectionRequestAsync(runId, trayId, revision, Guid.NewGuid(), 1,
            now.AddMinutes(4), "test-height", plan, strictRecipeExecution: true,
            motionConfiguration: config, heightResult: height,
            recipeApplicationReceipt: SemanticRecipeReceiptFixture.For(handoff));
    var first = await Resolve(Height(10.5, 11.0));
    var second = await Resolve(Height(11.5, 10.25));
    Assert.Equal([110.5, 111.0, 110.5, 111.0],
        first.Targets!.Select(target => target.Point.Z).ToArray());
    Assert.Equal([111.5, 110.25, 111.5, 110.25],
        second.Targets!.Select(target => target.Point.Z).ToArray());
    Assert.All(first.Targets!, target => Assert.Equal("Test/MeasuredHeightOffset", target.Source));
    Assert.Equal(["P01", "P03"], first.ExpectedObjects!.Select(x => x.Position.Id).ToArray());
    var wrong = Height(10.5, 11.0) with { ScopeId = "wrong-scope" };
    Assert.Equal("ProductHeightAssociationMismatch",
        (await Assert.ThrowsAsync<InvalidOperationException>(() => Resolve(wrong))).Message);
    var missing = Height(10.5, 11.0) with
    {
        Samples = [HeightSample.FromRaw("sample-a", 10.5, "mm", "SIM_REFERENCE")]
    };
    Assert.Equal("ProductHeightSampleInvalid",
        (await Assert.ThrowsAsync<InvalidOperationException>(() => Resolve(missing))).Message);
}

