[Fact]
public async Task CommittedHandoffResolvesExplicitFrozenFixedTargetsWithoutDefaultHeight()
{
    var root = TestConfiguration.Workspace();
    var catalog = TestConfiguration.RecipeCatalog(Path.Combine(root, "specs",
        "008-recipe-driven-inspection", "fixtures", "recipes.json"));
    var plan = RecipeRunPlanner.Build(catalog, "component-target", "S1",
        "TEST-TRAY-0101", ["P01"]);
    plan = plan with
    {
        Steps = plan.Steps.Select(step => step.Kind == RecipeStepKind.PositionForCapture
            ? step with { PointRef = "TEST-POINT-" + step.Camera, PhysicalSlotIndex = 1 }
            : step).ToArray(),
        PositionPayloads = new Dictionary<string, string>
        {
            ["P01"] = JsonSerializer.Serialize(new
            {
                resolvedSourcePoint = new { id = "TEST-SOURCE", version = "explicit/1",
                    x = 80, y = 90, z = 100, unit = "mm", frame = "SIM_MACHINE",
                    approvedSourceRef = "component-test://source" },
                resolvedDetectionTargets = new Dictionary<string, object>
                {
                    ["A"] = new { pointRef = "TEST-POINT-A", zMode = "ApprovedFixed",
                        zBasis = "component-explicit-fixed", approvedSourceRef = "component-test://A",
                        point = new { id = "TEST-POINT-A", version = "explicit/1",
                            x = 100, y = 100, z = 110, unit = "mm", frame = "SIM_MACHINE" } },
                    ["B"] = new { pointRef = "TEST-POINT-B", zMode = "ApprovedFixed",
                        zBasis = "component-explicit-fixed", approvedSourceRef = "component-test://B",
                        point = new { id = "TEST-POINT-B", version = "explicit/1",
                            x = 120, y = 100, z = 115, unit = "mm", frame = "SIM_MACHINE" } }
                }
            })
        }
    };
    var revision = RecipePlanRevision.Compute(plan);
    var runId = Guid.NewGuid();
    var trayId = Guid.NewGuid();
    var writeId = Guid.NewGuid();
    var now = DateTimeOffset.UtcNow;
    var identity = new WorkflowIdentity(runId, trayId, Guid.NewGuid().ToString("D"),
        Guid.NewGuid().ToString("D"), "component-target", "S1", ["P01"], now,
        "test:Operator", RunPurpose.Test, "public-1", "budget-1", "sim-1");
    var handoff = new PublicPreparationHandoffV2(
        PublicPreparationHandoffV2.CurrentSchemaVersion, Guid.NewGuid(), identity,
        "points-1", "capability-1", ["media://3d/1"], ["media://f/1"],
        ["result://height/1", "result://f/1"], "TEST-TRAY-0101",
        "recipe-plan://component", revision, "recipe-binding://component",
        ComponentEvidenceSource.Test, "VerifiedTestEvidence", ["write://1"],
        writeId, 1, now, "");
    handoff = handoff with { PayloadDigest = PublicPreparationHandoffV2.ComputePayloadDigest(handoff) };
    var committed = new CommittedPublicPreparationHandoffV2(handoff, handoff.HandoffId,
        writeId, 1, handoff.PayloadDigest);
    var query = new FixedHandoffQuery(committed);
    var consumer = new PublicPreparationHandoffV2Consumer(query);
    var config = JsonSerializer.Deserialize<PublicConfiguration>(File.ReadAllText(
        Path.Combine(root, "specs", "007-station01-integrated-loop", "examples",
            "public.virtual-loop.json")), new JsonSerializerOptions(JsonSerializerDefaults.Web))!;
    var request = await consumer.CreateDetectionRequestAsync(runId, trayId, revision,
        Guid.NewGuid(), 1, now.AddMinutes(2), "component-target", plan,
        strictRecipeExecution: true, motionConfiguration: config,
        recipeApplicationReceipt: SemanticRecipeReceiptFixture.For(handoff));
    Assert.True(request.IsValid);
    Assert.Equal(["A", "B"], request.Targets!.Select(target => target.Camera));
    Assert.All(request.Targets!, target => Assert.Equal("Approved/ConfiguredFixedZ", target.Source));
    Assert.Single(request.ExpectedObjects!);
    Assert.Equal("TEST-SOURCE", request.ExpectedObjects![0].Position.Id);
    Assert.Equal("Available", Assert.Single(catalog.Items).Availability);

    var missing = plan with { PositionPayloads = new Dictionary<string, string> { ["P01"] = "{}" } };
    var missingRevision = RecipePlanRevision.Compute(missing);
    var missingHandoff = handoff with { PlanRevision = missingRevision, PayloadDigest = "" };
    missingHandoff = missingHandoff with
    {
        PayloadDigest = PublicPreparationHandoffV2.ComputePayloadDigest(missingHandoff)
    };
    query.Value = new(missingHandoff, missingHandoff.HandoffId, writeId, 1,
        missingHandoff.PayloadDigest);
    var error = await Assert.ThrowsAsync<InvalidOperationException>(() =>
        consumer.CreateDetectionRequestAsync(runId, trayId, missingRevision,
            Guid.NewGuid(), 1, now.AddMinutes(2), "component-missing", missing,
            strictRecipeExecution: true, motionConfiguration: config,
            recipeApplicationReceipt: SemanticRecipeReceiptFixture.For(missingHandoff)));
    Assert.Equal("ProductPointCoordinatesMissing", error.Message);
}

