public void Q09IncompleteOrMisboundFaceCannotBecomeExecutable(string mutation)
{
    var source = Path.Combine(TestConfiguration.Workspace(), "specs",
        "008-recipe-driven-inspection", "fixtures", "usr-e-1.0.2", "recipes-q09.json");
    var changed = JsonNode.Parse(File.ReadAllText(source))!;
    var faces = changed["recipes"]![0]!["positions"]![0]!["resolvedDetectionTargetsByFace"]!;
    var target = faces["3"]!["C"]!;
    switch (mutation)
    {
        case "missing-camera": faces["3"]!.AsObject().Remove("C"); break;
        case "wrong-source-slot": target["zBasis"]!["measurementRef"]!["objectSlotId"] = "P03"; break;
        case "cross-face": target["executionStageId"] = "stage:2"; break;
    }
    var path = Path.Combine(Path.GetTempPath(), $"q09-invalid-{Guid.NewGuid():N}.json");
    try
    {
        File.WriteAllText(path, changed.ToJsonString());
        var invalid = TestConfiguration.RecipeCatalog(path);
        Assert.Equal("ProductFaceRoundMappingMissing", Assert.Single(invalid.Items).Restriction);
    }
    finally { File.Delete(path); }
}

