[InlineData("Q18", "CD,AB,CD,CD")]
[InlineData("Q20", "CD,CD,AB,CD")]
[InlineData("Q21", "CD,CD,CD,AB")]
public void VirtualMultiFaceCatalogsHaveCompleteFrozenTargetsAndWorkload(
    string caseId, string expectedSequence)
{
    var root = Path.Combine(TestConfiguration.Workspace(), "specs",
        "008-recipe-driven-inspection", "fixtures", "usr-e-1.0.2");
    var suffix = caseId.ToLowerInvariant();
    var path = Path.Combine(root, $"recipes-{suffix}.json");
    var catalog = TestConfiguration.RecipeCatalog(path);
    Assert.Equal("review-recipe-catalog/0.5", catalog.SchemaVersion);
    var item = Assert.Single(catalog.Items);
    Assert.Equal("Available", item.Availability);
    Assert.Equal($"R008-{caseId}", item.RecipeId);
    var sequence = expectedSequence.Split(',');
    var plan = RecipeRunPlanner.BuildExecutable(catalog, caseId, "S1",
        $"TEST-TRAY-01{caseId[1..]}", ["P01"]);
    Assert.Null(RecipeExecutionCoordinator.ValidateDetectionPlan(plan));
    Assert.Equal(sequence.SelectMany(pair => pair.Select(ch => ch.ToString())),
        plan.Steps.Where(step => step.Kind == RecipeStepKind.Capture)
            .Select(step => step.Camera));
    Assert.Equal(sequence.Length - 1,
        plan.Steps.Count(step => step.Kind == RecipeStepKind.FlipMember));
    Assert.DoesNotContain(plan.Steps, step => step.Kind == RecipeStepKind.RescanWholeTray);
    var workload = RecipeWorkloadCounter.Count(plan);
    Assert.Equal(sequence.Length * 2, workload.CaptureCount);
    Assert.Equal(sequence.Length, workload.FusionCount);
    Assert.Equal(sequence.Length * 3, workload.DetectionWorkerCalls);
    Assert.Equal(0, workload.HeightRescanCount);
    using var fixture = JsonDocument.Parse(File.ReadAllText(
        Path.Combine(root, $"fixture-{suffix}.json")));
    Assert.Equal(catalog.Digest,
        fixture.RootElement.GetProperty("recipeRef").GetProperty("catalogDigest").GetString());
    var media = JsonDocument.Parse(File.ReadAllText(
        Path.Combine(root, $"media-manifest-{suffix}.json")));
    Assert.Equal(sequence.SelectMany(pair => pair).Distinct().Order(),
        media.RootElement.GetProperty("images").EnumerateArray()
            .Where(image => image.GetProperty("role").GetString() == "Detection")
            .Select(image => image.GetProperty("camera").GetString()![0]).Order());
}

