[Fact]
public void Q03TwoFaceFixtureUsesInitialHeightAndExplicitFaceTargets()
{
    var path = Path.Combine(TestConfiguration.Workspace(), "specs",
        "008-recipe-driven-inspection", "fixtures", "recipes-q03.json");
    var catalog = TestConfiguration.RecipeCatalog(path);
    var item = Assert.Single(catalog.Items);
    Assert.Equal("review-recipe-catalog/0.5", catalog.SchemaVersion);
    Assert.Equal("Available", item.Availability);
    var plan = RecipeRunPlanner.BuildExecutable(catalog, "q03", "S1", "TEST-TRAY-0103", ["P01"]);
    Assert.Null(RecipeExecutionCoordinator.ValidateDetectionPlan(plan));
    Assert.Equal(new RecipeWorkload(4, 2, 6, 0) { FlipCount = 1 }, RecipeWorkloadCounter.Count(plan));
    Assert.Equal(new[] { RecipeStepKind.FlipMember },
        plan.Steps.Where(step => step.Kind is RecipeStepKind.FlipMember or
            RecipeStepKind.RescanWholeTray).Select(step => step.Kind));
    Assert.Equal(new[] { 1 }, plan.Steps.Where(step =>
        step.Kind == RecipeStepKind.PositionForCapture).Select(step => step.HeightRound)
        .Distinct().ToArray());
    Assert.Null(RecipeExecutionCoordinator.ValidateFaceRoundOrder(plan));
