    private static async Task<RunApiSnapshot> WaitForHandoffAsync(Station01HostFixture fixture, Guid runId)
    {
        var deadline = DateTimeOffset.UtcNow.AddSeconds(25);
        while (DateTimeOffset.UtcNow < deadline)
        {
            var snapshot = (await fixture.Client.GetFromJsonAsync<RunApiSnapshot>(
                $"/api/v1/station01/runs/{runId:D}"))!;
            if (snapshot.State == RunState.HandoffReady) return snapshot;
            if (snapshot.State == RunState.Blocked)
                Assert.Fail("Public preparation blocked: " + snapshot.ErrorCode);
            await Task.Delay(25);
        }
        throw new TimeoutException("Public handoff was not committed.");
    }

    private static ComponentEvidence Verified(ComponentKind component,
        ComponentEvidenceSource source) => new(component, ComponentEvidenceState.Verified,
        source, "Derived", "api-test/1", [$"evidence://{component}"],
        DateTimeOffset.UtcNow, "sha256:" + component);
}

