            // Wait for real semantic readiness before submitting the one request;
            // no accepted operation's deadline or observation is changed.
            var readiness = fixture.Host.Services.GetRequiredService<StartupReadiness>();
            using (var startupWatchdog = new CancellationTokenSource(TimeSpan.FromSeconds(10)))
            {
                while (true)
                {
