            var awaiting = await WaitForStateAsync(fixture, receipt.RunId,
                RunState.AwaitingManualRemoval, TimeSpan.FromSeconds(25));
            var evidenceBefore = (await fixture.Client.GetFromJsonAsync<Station01RunEvidenceApi>(
                $"/api/v1/station01/runs/{receipt.RunId:D}/evidence"))!;
            Assert.Equal("AwaitingFinalUnloadCompletion", evidenceBefore.FinalResult);
            Assert.Null(evidenceBefore.FinalSourceMatrix);
            Assert.DoesNotContain(evidenceBefore.Stages, x => x.EventType ==
