            Assert.All(persistedStages, stage => Assert.Equal(completion.TrayId, stage.TrayId));
            Assert.All(persistedStages.Where(x => !string.IsNullOrWhiteSpace(x.PlanRevision)),
                stage => Assert.Equal(completion.PlanRevision, stage.PlanRevision));
            var physicalStages = persistedStages.Where(x => x.Stage is "Sorting" or
                "UnloadPreparation" or "UnlockObservation").ToArray();
            Assert.Single(physicalStages.Select(x => x.ConnectionEpoch).Distinct());
            Assert.Contains(persistedStages, x =>
                x.EventId == completion.DetectionCompletedEventId);
            Assert.Contains(persistedStages, x =>
                x.EventId == completion.SortingCompletedEventId);
            Assert.Contains(persistedStages, x =>
                x.EventId == completion.UnloadPreparationCompletedEventId);
            Assert.Single(await db.StageEvents.Where(x => x.RunId == receipt.RunId &&
                x.EventType == StageEventType.ManualTrayRemovalConfirmed.ToString()).ToListAsync());
            Assert.Single(await db.StageEvents.Where(x => x.RunId == receipt.RunId &&
                x.EventType == StageEventType.FinalUnloadCompleted.ToString()).ToListAsync());
            Assert.Equal(2, await db.ComponentEvidenceMatrices.CountAsync(x =>
                x.RunId == receipt.RunId));
            var persistedRun = await db.Runs.SingleAsync(x => x.RunId == receipt.RunId);
            Assert.Equal(RunState.Completed, persistedRun.State);
            Assert.Equal(TerminalOutcome.Completed, persistedRun.Terminal);
        }
    }

    private static async Task<RunApiSnapshot> WaitForStateAsync(Station01HostFixture fixture,
        Guid runId, RunState expected, TimeSpan timeout)
    {
        var deadline = DateTimeOffset.UtcNow + timeout;
        while (DateTimeOffset.UtcNow < deadline)
        {
            var snapshot = (await fixture.Client.GetFromJsonAsync<RunApiSnapshot>(
                $"/api/v1/station01/runs/{runId:D}"))!;
            if (snapshot.State == expected) return snapshot;
            if (snapshot.State is RunState.Blocked or RunState.RecoveryRequired)
                Assert.Fail($"Run stopped at {snapshot.State}: {snapshot.ErrorCode}");
            await Task.Delay(25);
        }
        throw new TimeoutException($"Run did not reach {expected}.");
    }

}

