            if (snapshot.Events.Any(e => e.StartsWith("DetectionRequestPrepared:", StringComparison.Ordinal))) break;
            await Task.Delay(20, token);
        } while (true);
        // The real Host has already consumed its live coordinator outcome. This
        // readback only verifies that successful request; it never authorizes a
        // restart, new product action or reconstruction of an old approval.
