        Assert.Equal(live.RunId, approval.Correlation.RunId);
        Assert.Equal(liveTrayId, approval.Correlation.TrayId);
        Assert.Contains(approval.RequiredCommits, c => c.WriteId == liveCommitted.Handoff.WriteId &&
            c.PersistedRevision == liveCommitted.Handoff.CommittedRevision);
        var preparedOperation = Guid.ParseExact(Assert.Single(snapshot.Events,
            e => e.StartsWith("DetectionRequestPrepared:", StringComparison.Ordinal)).Split(':')[1], "N");
        var request = await consumer.CreateDetectionRequestAsync(live.RunId, liveTrayId,
            liveCommitted.Handoff.PlanRevision, preparedOperation, approval.Correlation.ConnectionEpoch,
            DateTimeOffset.UtcNow.AddSeconds(120), "verify-live-handoff-projection",
