    [Fact]
    public async Task FrozenTestManifestSelectsDistinctReadableAAndBMedia()
    {
        var workspace = Station01HostFixture.FindWorkspace();
        var manifest = Path.Combine(workspace, "specs", "008-recipe-driven-inspection",
            "fixtures", "media-manifest.json");
        var capture = new FileBackedCapture(manifest);
        var run = Guid.NewGuid();

        async Task<string> ReadAsync(string camera)
        {
            var id = Guid.NewGuid();
            var envelope = new PortEnvelope(run, Guid.NewGuid(), 1, Guid.NewGuid(),
                "q01-component", "1.0", "Test", 1, 30, "component-clock");
            var request = new CaptureRequest(envelope, id, CaptureRole.Detection,
                "P01", "1.0", "P01", "1.0", camera, "TestLight",
                Guid.NewGuid(), 4 * 1024 * 1024);
            var completed = new TaskCompletionSource<byte[]>(
                TaskCreationOptions.RunContinuationsAsynchronously);
            await capture.RequestCaptureAsync(request, value =>
            {
                if (value.Kind == CaptureEventKind.MediaTaken && value.Buffer is { Length: > 0 })
                    completed.TrySetResult(value.Buffer);
                if (value.Kind == CaptureEventKind.Failed)
                    completed.TrySetException(new IOException(value.ErrorCode));
            }, CancellationToken.None);
            var bytes = await completed.Task.WaitAsync(TimeSpan.FromSeconds(8));
            return Convert.ToHexString(SHA256.HashData(bytes));
