        Assert.Equal("CCFE5D6917F42E8828C903B177B2862D9687B92220E98D196A46F588DE008907", digests[0]);
        Assert.Equal("3E53F61CBF7B61B09F34FF2EF32C7181220517C40430D83E4E7839AA863BAEEB", digests[1]);
        Assert.Equal(2, capture.TriggerCount(CaptureRole.Detection));
    }
}

