        Assert.EndsWith(":M01", binding.RootElement.GetProperty("objectId").GetString());
        if (workerError) Assert.Equal("ControlledEDecodeFailure", binding.RootElement.GetProperty("issue").GetString());
        else if (missingCode) Assert.Equal("ECodeNoResult", binding.RootElement.GetProperty("issue").GetString());
        else Assert.StartsWith("TEST-BASE-A:", binding.RootElement.GetProperty("externalCode").GetString());
        var captures = payloads.Where(p => p.RootElement.TryGetProperty("stepSequence", out _) && p.RootElement.TryGetProperty("RelativeKey", out _)).ToArray();
        Assert.Equal(7, captures.Length);
        Assert.All(captures.Where(p => p.RootElement.GetProperty("objectId").GetString()!.EndsWith(":M02")),
            p => Assert.Equal(1, p.RootElement.GetProperty("localFace").GetInt32()));
    }
    finally { foreach (var payload in payloads) payload.Dispose(); }
    var media = await rig.Host.Client.GetFromJsonAsync<JsonElement>($"/api/v1/station01/runs/{receipt.RunId:D}/media");
    var eMedia = Assert.Single(media.GetProperty("items").EnumerateArray(), x => x.GetProperty("role").GetString() == "E");
    Assert.EndsWith(":M01", eMedia.GetProperty("objectId").GetString());
    Assert.Equal(1, eMedia.GetProperty("localFace").GetInt32());
    var queried = await rig.Host.Client.GetFromJsonAsync<RunApiSnapshot>($"/api/v1/station01/runs/{receipt.RunId:D}");
    Assert.Equal(2, queried!.Results.Count(x => x.Kind == "Part"));
    Assert.Equal(3, queried.Results.Count(x => x.Kind == "Face"));
    Assert.Equal(ngParts ? "NG" : "OK", Assert.Single(queried.Results, x => x.Kind == "Assembly").Disposition);
    if (ngParts)
    {
        Assert.Contains(queried.Results, x => x.Kind == "Face" && x.Disposition == "Pending");
    }
    return folder;
}

