public async Task CommittedV2HandoffContinuesThroughThreeStagesOverFormalTcpAndSqlite()
{
        await using var rig = await VirtualLoopTestRig.CreateAsync(useCurrentRecipe: true);
        var fixture = rig.Host;
        var (request, accepted, receipt) = await rig.StartAsync();
        var context = request.ContextJson;
        Assert.Equal(HttpStatusCode.Accepted, accepted.StatusCode);
