        var options = fixture.Host.Services.GetRequiredService<DbContextOptions<Station01DbContext>>();
        await using var db = new Station01DbContext(options);
        var handoff = await db.PublicPreparationHandoffsV2.SingleAsync(x => x.RunId == receipt.RunId);
        Assert.True(context.Contains(handoff.TrayId.ToString("D"), StringComparison.OrdinalIgnoreCase));
        var completed = await db.StageEvents.Where(x => x.RunId == receipt.RunId &&
                x.EventType == StageEventType.Completed.ToString())
            .Select(x => x.Stage).ToListAsync();
        Assert.Contains(WholeTrayWorkflowStage.Detection.ToString(), completed);
        Assert.Contains(WholeTrayWorkflowStage.Sorting.ToString(), completed);
        Assert.Contains(WholeTrayWorkflowStage.UnloadPreparation.ToString(), completed);
        var completion = await db.WholeTrayCompletions.SingleAsync(x => x.RunId == receipt.RunId);
        var readyMatrix = await db.ComponentEvidenceMatrices.SingleAsync(x =>
            x.MatrixId == completion.SourceMatrixId);
        Assert.Equal(EvidenceScope.SoftwareLoopOnly.ToString(), readyMatrix.Scope);
        Assert.Single(await db.StageEvents.Where(x => x.RunId == receipt.RunId &&
            x.EventType == StageEventType.ObservedUnlocked.ToString()).ToListAsync());
        Assert.Empty(await db.StageEvents.Where(x => x.RunId == receipt.RunId &&
            x.EventType == StageEventType.FinalUnloadCompleted.ToString()).ToListAsync());
}

private static async Task RunScenarioAsync(Action<IServiceCollection> configure,
    Func<Station01HostFixture, RunApiSnapshot, Station01DbContext, Task> assert)
{
    await using var rig = await VirtualLoopTestRig.CreateAsync(configure, useCurrentRecipe: true);
    var fixture = rig.Host;
    var (request, response, receipt) = await rig.StartAsync();
    Assert.Equal(HttpStatusCode.Accepted, response.StatusCode);
    // Overall Test wait includes actual public camera/worker calls; PLC and stage limits are unchanged.
    var end = DateTimeOffset.UtcNow.AddSeconds(180);
    RunApiSnapshot snapshot;
    while (true)
    {
        snapshot = (await fixture.Client.GetFromJsonAsync<RunApiSnapshot>(
            $"/api/v1/station01/runs/{receipt.RunId:D}"))!;
        if (snapshot.State == RunState.AwaitingManualRemoval ||
            snapshot.State is RunState.Blocked or RunState.RecoveryRequired) break;
        if (DateTimeOffset.UtcNow >= end)
            Assert.Fail($"Scenario timed out at {snapshot.State}: {snapshot.ErrorCode}");
        await Task.Delay(500);
    }
    var dbOptions = fixture.Host.Services.GetRequiredService<DbContextOptions<Station01DbContext>>();
    await using var db = new Station01DbContext(dbOptions);
    await rig.SaveEvidenceAsync("three-stage-injected", request, response, receipt,
        new { snapshot.State, snapshot.ErrorCode, snapshot.WholeTaskState });
    await assert(fixture, snapshot, db);
}

